const calculatePetitionTypeDistribution = (realPetitions: any[]) => {
  console.log('📊 CALCULANDO DISTRIBUIÇÃO REAL DE TIPOS...');

  if (realPetitions.length === 0) {
    // Se não há dados, retornar distribuição vazia
    return [
      { name: 'Nenhuma petição', value: 100, color: '#94A3B8' }
    ];
  }

  // Contar tipos reais das petições
  const typeCounts = realPetitions.reduce((acc: any, petition: any) => {
    const type = petition.tipo || petition.type || petition.categoria || 'Outros';
    acc[type] = (acc[type] || 0) + 1;
    return acc;
  }, {});

  const total = realPetitions.length;

  // Converter contagens em percentuais
  const realDistribution = Object.entries(typeCounts).map(([type, count]: [string, any]) => ({
    name: type,
    value: Math.round((count / total) * 100),
    color: getColorForType(type) // função para cores
  }));

  console.log('✅ DISTRIBUIÇÃO REAL CALCULADA:', realDistribution);
  return realDistribution;
};

// Função para cores dinâmicas
const getColorForType = (type: string) => {
  const colorMap: { [key: string]: string } = {
    'Inicial': '#3B82F6',
    'Contestação': '#EF4444', 
    'Recurso': '#10B981',
    'Agravo': '#F59E0B',
    'Outros': '#8B5CF6',
    // Adicionar mais cores conforme necessário
  };
  return colorMap[type] || '#6B7280';
};
```

